package com.bankpli.javabank.audit;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuditService {private final AuditRepository repository;public AuditService(AuditRepository r){repository=r;}@Transactional public AuditRecord append(String type,String details){return repository.save(new AuditRecord(type,details));}@Transactional(readOnly=true)public List<AuditRecord> list(){return repository.findAllByOrderByOccurredAtDesc();}public ParsedTransaction parse(String line){if(line==null)throw new IllegalArgumentException("Line is required");String[] p=line.split(",",-1);if(p.length<4)throw new IllegalArgumentException("Expected id,type,amount,description");return new ParsedTransaction(p[0].trim(),p[1].trim(),new java.math.BigDecimal(p[2].trim()),p[3].trim());}public record ParsedTransaction(String id,String type,java.math.BigDecimal amount,String description){}}
